import { bitbucketDraftMarkedReady, bitbucketRepositoryHost } from "./binding.js";
export function bitbucketSeenPullRequestKey(repository, id) {
    const host = bitbucketRepositoryHost(repository);
    return `bitbucket-pr-state:${host}:${repository.fullName.toLowerCase()}#${id}`;
}
export async function readBitbucketSeenPullRequest(kv, key) {
    const value = await kv.get(key);
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
        return undefined;
    }
    const headSha = typeof value.headSha === "string" && value.headSha !== "" ? value.headSha : undefined;
    const draft = typeof value.draft === "boolean" ? value.draft : undefined;
    if (headSha === undefined && draft === undefined) {
        return undefined;
    }
    return { headSha, draft };
}
export async function writeBitbucketSeenPullRequest(kv, key, seen) {
    const value = {};
    if (seen.headSha !== undefined) {
        value.headSha = seen.headSha;
    }
    if (seen.draft !== undefined) {
        value.draft = seen.draft;
    }
    if (value.headSha === undefined && value.draft === undefined) {
        return;
    }
    await kv.put(key, value);
}
/** A short hex hash and the full hash it abbreviates name the same commit. */
function sameCommit(a, b) {
    const [short, long] = a.length <= b.length ? [a, b] : [b, a];
    return /^[0-9a-f]{7,}$/i.test(short) && long.toLowerCase().startsWith(short.toLowerCase());
}
/**
 * The record to store after a delivery. A field the payload omits keeps its
 * stored value, and a short hash never replaces the full hash it abbreviates.
 */
export function mergeBitbucketSeenPullRequest(seen, pullRequest) {
    const incoming = pullRequest.headSha;
    const stored = seen?.headSha;
    const keepStored = incoming === undefined ||
        (stored !== undefined && sameCommit(stored, incoming) && stored.length >= incoming.length);
    return {
        headSha: keepStored ? stored : incoming,
        draft: pullRequest.draft ?? seen?.draft,
    };
}
/**
 * Whether the default pull-request path starts a turn. A head change wins,
 * then a draft that becomes ready, then the first open delivery that has a
 * head. A later edit of the same head does not.
 */
export function bitbucketPullRequestShouldReview(input) {
    const pullRequest = input.pullRequest;
    if (pullRequest.action === "created") {
        return true;
    }
    if (pullRequest.action !== "updated") {
        return false;
    }
    const head = pullRequest.headSha;
    const payloadHeadChanged = pullRequest.previousHeadSha !== undefined && pullRequest.previousHeadSha !== head;
    const storedHeadChanged = head !== undefined &&
        input.seen?.headSha !== undefined &&
        !sameCommit(head, input.seen.headSha);
    if (payloadHeadChanged || storedHeadChanged) {
        return true;
    }
    const draftReady = bitbucketDraftMarkedReady(input.payload, pullRequest.draft) ||
        (input.seen?.draft === true && pullRequest.draft === false);
    if (draftReady) {
        return true;
    }
    const closed = pullRequest.state === "MERGED" ||
        pullRequest.state === "DECLINED" ||
        pullRequest.state === "SUPERSEDED";
    return input.seen?.headSha === undefined && head !== undefined && !closed;
}
